    benefits: [{"title": "Practice Throughout the Day", "body": "Skills worked on in therapy can be practiced in real daily routines, such as meals, self-care and household tasks."}, {"title": "A Homelike Setting", "body": "Care is provided in apartments, rooms and homes designed to feel like home rather than a clinic."}, {"title": "One Coordinated Team", "body": "Nurses, therapists, case managers, recreational therapists, social workers, counselors and residential care assistants work as one team."}, {"title": "A Continuum of Care", "body": "Residential, semi-independent apartment and outpatient programs make it easier to adjust care over time."}],
